const thumbScene=new THREE.Scene();thumbScene.environment=studioEnvironment;thumbScene.environmentIntensity=.65;thumbScene.add(new THREE.HemisphereLight('#fff4df','#7b8876',2));const thumbKey=new THREE.DirectionalLight('#fff8f0',3);thumbKey.position.set(-2,4,5);thumbScene.add(thumbKey);const thumbCamera=new THREE.PerspectiveCamera(32,1.35,.01,20);const thumbRenderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});thumbRenderer.setSize(220,164);thumbRenderer.setPixelRatio(1);thumbRenderer.toneMapping=THREE.ACESFilmicToneMapping;thumbRenderer.outputColorSpace=THREE.SRGBColorSpace;const thumbs={};for(const d of HOLD_LIBRARY){const h=createHold(d.id,d.previewColor||'#bd6849');thumbScene.add(h);const span=Math.max(d.w,d.h);thumbCamera.position.set(span*.75,span*.8,span*4.55);thumbCamera.lookAt(0,0,d.d*.25);thumbRenderer.render(thumbScene,thumbCamera);thumbs[d.id]=thumbRenderer.domElement.toDataURL('image/png');thumbScene.remove(h);disposeHold(h)}thumbRenderer.dispose();thumbRenderer.forceContextLoss();$$('[data-thumb]').forEach(img=>img.src=thumbs[img.dataset.thumb]);
