 function mapPose(p){const oc=old[p.sector],results=Object.fromEntries(LIMBS.map(k=>[k,mapSurface(oc,configs,p.targets[k])])),counts={};for(const r of Object.values(results))if(r)counts[r.sector]=(counts[r.sector]||0)+1;const si=Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0]??configs.findIndex(c=>c.sourceId===oc.id);if(+si<0)throw Error('This panel is used by a beta pose. Keep the panel or start a new layout.');const targetConfig=configs[+si],cs=structuredClone(p.contacts||defaultContacts()),out={};for(const k of LIMBS){const r=results[k];if(r){out[k]=globalToLocal(targetConfig,localToGlobal(configs[r.sector],r.point));cs[k].sector=r.sector;delete cs[k].orientation;delete cs[k].anchor;delete cs[k].socket;}else{out[k]=globalToLocal(targetConfig,localToGlobal(oc,p.targets[k]));cs[k].attached=false;delete cs[k].anchor;delete cs[k].socket;}}return{...p,sector:+si,targets:out,contacts:cs};}
