 const current=removed.has(before.avatarSector)?idle:mapPose({sector:before.avatarSector,targets:before.targets,contacts:before.contacts});next.avatarSector=current.sector;next.targets=current.targets;next.contacts=current.contacts;next.frames=before.frames.filter(p=>!removed.has(p.sector)).map(mapPose);if(!next.frames.length)next.frames=[structuredClone(idle)];next.frameIndex=Math.min(next.frameIndex,next.frames.length-1);next.activeRouteKey=current.sector+':'+before.activeRouteKey.split(':').slice(1).join(':');next.routeBetas=Object.fromEntries(Object.entries(before.routeBetas||{}).filter(([k,b])=>b.frames?.length&&b.frames.every(p=>!removed.has(p.sector))).map(([k,b])=>[mapPose(b.frames[0]).sector+':'+k.split(':').slice(1).join(':'),{...b,frames:b.frames.map(mapPose)}]));next.ruler=null;if(removed.has(before.avatarSector)){next.name='New line';next.hip=0;next.posture=defaultPosture();next.activeRouteKey=mapped.find(h=>!h.type.startsWith('volume-'))?mapped.find(h=>!h.type.startsWith('volume-')).si+':'+mapped.find(h=>!h.type.startsWith('volume-')).color:'0:#d96b4f';}
