 demo:()=>{const hs=holds.filter(h=>routeKeyForHold(h)==='0:#d96b4f');if(hs.length<6){toast('The demo uses the original orange route. Open a fresh studio tab to view it.');return null;}chooseBetaRoute('0:#d96b4f');setMode('beta');const nearest=(x,y)=>[...hs].sort((a,b)=>Math.hypot(a.position.x-x,a.position.y-y)-Math.hypot(b.position.x-x,b.position.y-y))[0];const make=(positions,rise=0,autoFit=true)=>{const cs=defaultContacts(),ts={};for(const k of LIMBS){const h=nearest(...positions[k]),anchor=h.position.clone();if(k.endsWith('f')&&nearest(...positions.lf)===nearest(...positions.rf))anchor.x+=k==='lf'?-.045:.045;cs[k]={...cs[k],anchor:anchor.toArray(),sector:0,socket:h.userData.socket};ts[k]=holdContact(h,sectors[0].face.localToWorld(anchor.clone()),k.endsWith('h'),body.height/172,sectors,cs[k]);}return{sector:0,contacts:cs,targets:ts,hip:0,posture:{...defaultPosture(),rise,autoFit,depth:.4},duration:2.5};};const low={lh:[-.42,2.57],rh:[.12,3.9],lf:[.03,1.78],rf:[.03,1.78]},high={...low,lh:[.75,3.12],lf:[-.42,2.57],rf:[-.42,2.57]};return [make(low,-.22,false),make(low,.16,false),make(high,.1,true)];},
