function dynamicClearance(si){const bounds=holds.filter(h=>h.userData.si===si).map(h=>{h.updateMatrix();if(!h.geometry.boundingBox)h.geometry.computeBoundingBox();return h.geometry.boundingBox.clone().applyMatrix4(h.matrix);});return(p,r)=>bounds.reduce((z,b)=>p.x+r>=b.min.x&&p.x-r<=b.max.x&&p.y+r>=b.min.y&&p.y-r<=b.max.y?Math.max(z,b.max.z+r):z,.132+r);}

